new = '''class BranchingPacker:
    """Pack weighted logical out-trees into reserved logical capacity.

    Trees grow one logical arc at a time.  Before an arc is used the exact
    largest safe weight is computed with one min-cut probe, which keeps the
    multi-root packing invariant intact so every started tree can be finished.
    """

    def __init__(self, parts, rcap, rdem):
        self.parts = sorted(parts)
        self.idx = {v: i for i, v in enumerate(self.parts)}
        self.n = len(self.parts)
        self.rcap = {}
        for k, v in rcap.items():
            if v > 0:
                self.rcap[k] = v
        self.rdem = dict(rdem)
        self.out = {}
        for (a, b) in self.rcap:
            self.out.setdefault(a, []).append(b)
        for v in self.out:
            self.out[v].sort()
        # flow network: participants + one probe source + one node per grown tree
        self.fg = FlowGraph(self.n + 1)
        self.sig = self.n
        self.arc_of = {}
        for (a, b), c in self.rcap.items():
            self.arc_of[(a, b)] = self.fg.add_arc(self.idx[a], self.idx[b], c)
        self.sig_arc = {}
        for u in self.parts:
            self.sig_arc[u] = self.fg.add_arc(self.sig, self.idx[u], 0)
        self.sig_x = self.fg.add_arc(self.sig, 0, 0)   # placeholder, retargeted
        self.trees = {}
        self.next_tid = 0
        self.single = {}
        for v in self.parts:
            if self.rdem.get(v, 0) > 0:
                self._new_tree(v, self.rdem[v], {v}, [])

    def _new_tree(self, root, w, R, edges):
        tid = self.next_tid
        self.next_tid += 1
        snode = None
        sig_arc = None
        if len(R) > 1:
            snode = self.fg.add_node()
            for v in R:
                self.fg.add_arc(snode, self.idx[v], INF)
            sig_arc = self.fg.add_arc(self.sig, snode, w)
        self.trees[tid] = {'root': root, 'w': w, 'R': set(R),
                           'edges': list(edges), 'snode': snode,
                           'sig': sig_arc}
        if snode is None:
            self.single[root] = self.single.get(root, 0) + w
        return tid

    def _drop_tree(self, tid):
        T = self.trees[tid]
        if T['snode'] is None:
            self.single[T['root']] -= T['w']
        else:
            self.fg.set_cap(T['sig'], 0)
        del self.trees[tid]

    def test_edge(self, tid, x, y):
        T = self.trees[tid]
        cap_xy = self.rcap.get((x, y), 0)
        if cap_xy <= 0:
            return 0
        fg = self.fg
        c_sum = 0
        ix = self.idx[x]
        for u, w in self.single.items():
            if w <= 0:
                continue
            if T['snode'] is None and T['root'] == u:
                w -= T['w']
            self.fg.set_cap(self.sig_arc[u], w if w > 0 else 0)
            c_sum += w if w > 0 else 0
        for oid, O in self.trees.items():
            if oid == tid or O['snode'] is None:
                continue
            fg.set_cap(O['sig'], O['w'])
            c_sum += O['w']
        fg.set_cap(self.sig_x, INF)
        fg.to[self.sig_x] = ix
        val = fg.maxflow(self.sig, self.idx[y])
        fg.set_cap(self.sig_x, 0)
        chunks = val - c_sum
        if chunks > T['w']:
            chunks = T['w']
        if chunks > cap_xy:
            chunks = cap_xy
        return chunks if chunks > 0 else 0

    def generate(self):
        nparts = self.n
        queue = sorted(self.trees.keys())
        done = []
        guard = 0
        while queue:
            guard += 1
            if guard > 200000:
                raise RuntimeError('branching packer did not converge')
            tid = queue.pop(0)
            T = self.trees.get(tid)
            if T is None:
                continue
            bfs = list(T['R'])
            head = 0
            while head < len(bfs):
                x = bfs[head]
                head += 1
                cands = [(b, self.rcap[(x, b)]) for b in self.out.get(x, ())
                         if b not in T['R'] and self.rcap.get((x, b), 0) > 0]
                cands.sort(key=lambda e: (-e[1], e[0]))
                for y, _c in cands:
                    if y in T['R'] or self.rcap.get((x, y), 0) <= 0:
                        continue
                    chunks = self.test_edge(tid, x, y)
                    if chunks <= 0:
                        continue
                    bfs.append(y)
                    if chunks < T['w']:
                        ntid = self._new_tree(T['root'], T['w'] - chunks,
                                              T['R'], T['edges'])
                        queue.append(ntid)
                        if T['snode'] is None:
                            self.single[T['root']] -= T['w']
                        T['w'] = chunks
                        if T['snode'] is None:
                            self.single[T['root']] += chunks
                        else:
                            self.fg.set_cap(T['sig'], chunks)
                    T['edges'].append((x, y))
                    T['R'].add(y)
                    if T['snode'] is None:
                        if len(T['R']) > 1:
                            self.single[T['root']] -= T['w']
                            sn = self.fg.add_node()
                            for v in T['R']:
                                self.fg.add_arc(sn, self.idx[v], INF)
                            sa = self.fg.add_arc(self.sig, sn, T['w'])
                            T['snode'] = sn
                            T['sig'] = sa
                    else:
                        self.fg.add_arc(T['snode'], self.idx[y], INF)
                    self.rcap[(x, y)] -= chunks
                    self.fg.set_cap(self.arc_of[(x, y)], self.rcap[(x, y)])
                    if self.rcap[(x, y)] <= 0:
                        del self.rcap[(x, y)]
            if len(T['R']) != nparts:
                raise RuntimeError('branching incomplete for root %r' % (T['root'],))
            done.append((T['root'], T['w'], list(T['edges'])))
            self._drop_tree(tid)
        return done


'''
